{
 "summary": "Lean proves two statements. (1) There is a connected bipartite 2-degenerate graph H on Fin q, with both colour classes of max degree > 2 in every proper 2-colouring, and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all large n. (2) The universal Erdős degeneracy statement, ex(n,H) = O(n^{2−1/r}) for every bipartite r-degenerate H, is false. The statements match the paper's Theorem 1.2 and its consequence; the main caveat is that the Lean statements differ slightly in strength (extra conjuncts, and r = 0 included in the conjecture), which is harmless.",
 "glossary": [
  {"decl": "TwoDegenerateGraphs.neighborsWithin", "line": 8, "plain": "The set of neighbours of v inside the finite vertex set s.", "standard_concept": "N(v) ∩ s", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours inside s.", "standard_concept": "r-degenerate graph", "matches_standard": "yes", "note": "Using induced subgraphs on finite sets is equivalent to the paper's 'every nonempty subgraph has a vertex of degree ≤ r'."},
  {"decl": "TwoDegenerateGraphs.IsTwoDegenerate", "line": 17, "plain": "IsDegenerate 2.", "standard_concept": "2-degenerate", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.DegeneracyConjectureStatement", "line": 20, "plain": "For all r, q and every bipartite r-degenerate H on Fin q, ex(n,H) = O(n^{2−1/r}) as n→∞ (exponent cast from ℕ 2).", "standard_concept": "Erdős's degeneracy conjecture (3)", "matches_standard": "partly", "note": "It also quantifies over r = 0, where 1/(0:ℝ) = 0 and the exponent is 2. The paper's conjecture is for r ≥ 1. The `0 ≤ r` hypothesis is vacuous. The r = 0 case is true, so this is harmless."},
  {"decl": "SimpleGraph.extremalNumber (Mathlib)", "line": 24, "plain": "Max edges of an H-free graph on Fin n, where H-free means no injective-homomorphism copy of H.", "standard_concept": "ex(n,H)", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q that is connected, bipartite and 2-degenerate. In every proper 2-colouring and for each colour class, the maximum degree in that class is > 2. There also exist c, ε > 0 such that, for all sufficiently large n, c·n^{3/2+ε} ≤ ex(n,H)."},
  {"theorem": "TwoDegenerateGraphs.not_erdos_146", "line": 43, "plain": "It is not true that every bipartite r-degenerate graph H on Fin q has ex(n,H) = O(n^{2−1/r}) for all r, q."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Conjecture (3) disproof", "plain": "Erdős's conjecture that bipartite r-degenerate H have ex(n,H) = O(n^{2−1/r}) fails already for r = 2."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.2", "lean_theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "relation": "lean_stronger", "why": "Same existence and lower bound, plus an extra conjunct that both colour classes have max degree > 2 in every proper 2-colouring. This rules out the known 'one side has max degree ≤ r' case."},
  {"paper_ref": "Disproof of Erdős's degeneracy conjecture (3)", "lean_theorem": "TwoDegenerateGraphs.not_erdos_146", "relation": "equivalent", "why": "The negation of the universal statement is witnessed by r = 2, where the exponent is 3/2. The Lean statement also includes r = 0, which is true, so it is only trivially different."},
  {"paper_ref": "Theorem 1.1 (compactness)", "lean_theorem": null, "relation": "not_formalized", "why": "Covered elsewhere (sibling file)."}
 ],
 "flags": [
  {"id": "F1", "category": "other", "severity": "low", "decl": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "line": 33, "paper_ref": "Theorem 1.2", "explanation": "The extra conjunct on max degree per colour class is not in the paper's Theorem 1.2 as excerpted. It makes the existence claim stronger, so it is harmless. Both sup values must be positive, since a sup over an empty set is 0, and that is consistent with the claim.", "polarity": "lean stronger", "probe_idea": null},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "TwoDegenerateGraphs.DegeneracyConjectureStatement", "line": 20, "paper_ref": "Conjecture (3)", "explanation": "The statement ranges over all r : ℕ including r = 0 (junk value 1/0 = 0, exponent 2) and has a vacuous `0 ≤ r`. The negation is therefore marginally weaker than the negation of the r ≥ 1 conjecture. The r = 2 counterexample refutes both.", "polarity": "lean weaker", "probe_idea": "Restate with 1 ≤ r (or just r = 2) and check that not_erdos_146's proof still goes through."}
 ],
